package com.medisphere.milestone3.controller;
import com.medisphere.milestone3.dto.*;import com.medisphere.milestone3.repository.*;import com.medisphere.milestone3.service.AnomalyService;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/dashboard") @CrossOrigin(origins="*") public class DashboardController{private final VitalsRepository vitals;private final AlertRepository alerts;private final AnomalyService anomaly;public DashboardController(VitalsRepository v,AlertRepository a,AnomalyService n){vitals=v;alerts=a;anomaly=n;}@GetMapping public DashboardResponse get(){long out=vitals.findTop50ByOrderByIdDesc().stream().filter(x->!"NORMAL".equals(x.getHeartRateStatus())||!"NORMAL".equals(x.getSpo2Status())||!"NORMAL".equals(x.getTemperatureStatus())||!"NORMAL".equals(x.getRespiratoryRateStatus())||!"NORMAL".equals(x.getSystolicBpStatus())||!"NORMAL".equals(x.getDiastolicBpStatus())).count();var m=alerts.countBySuppressedTrueAndAlertTimestampAfter(java.time.LocalDateTime.now().minusHours(1));var p=anomaly.precision();return new DashboardResponse(out,m,p.precisionPercent(),p.targetMet());}}
